const salonOf=c=>(ME&&ME.salons||[]).find(s=>s.code===c)||null;
function place(pop,btn){const r=btn.getBoundingClientRect(),hr=host.getBoundingClientRect();const w=Math.min(340,innerWidth-24);let x=r.left+r.width/2-w/2;x=Math.max(12,Math.min(x,innerWidth-w-12));
  pop.style.position="fixed";pop.style.left=x+"px";pop.style.top=(r.bottom+12)+"px";pop.style.setProperty("--ax",(r.left+r.width/2-x-7)+"px")}
